mapper.select:
SELECT COUNT(*) FROM aigc_work
WHERE user_id = #{userId}

    AND creation_type = #{creationType}

SELECT
    aw.work_id as workId,
    aw.url as url,
    ast.style_name as styleName
FROM aigc_work aw
LEFT JOIN aigc_style ast ON aw.style_id = ast.style_id
WHERE aw.user_id = #{userId}

    AND aw.creation_type = #{creationType}

ORDER BY aw.generate_time DESC
LIMIT #{limit} OFFSET #{offset}
